function avg(list, key) { return list.length ? list.reduce((s, x) => s + Number(x[key] || 0), 0) / list.length : 0; }
function resourceScore(r) { return (r.direction === "low_good" ? 6 - Number(r.current || 1) : Number(r.current || 1)) * 20; }
function resourceGap(r) { return r.direction === "low_good" ? Number(r.current || 1) - Number(r.target || 1) : Number(r.target || 1) - Number(r.current || 1); }
function strategyScore(s) { return Number(s.acceptance || 0) * 3 + Number(s.control || 0) * 3 + Number(s.innovation || 0) * 2 + Number(s.speed || 0) - Number(s.risk || 0) * 3; }
function compute(s) { const resources=safeArray(s.resources), personas=safeArray(s.personas), assumptions=safeArray(s.assumptions), interventions=safeArray(s.interventions), strategies=safeArray(s.strategies); const res=resources.length?resources.reduce((a,r)=>a+resourceScore(r),0)/resources.length:60; const risky=assumptions.filter(a=>a.evidence==="niedrig"||a.uncertainty==="hoch"); const hasPrivacy=interventions.some(i=>/daten|datenschutz|grenze|faq|dokumentation/i.test(`${i.name} ${i.target}`)); const hasParticipation=interventions.some(i=>/einwand|beteilig|freiwillig|workshop|jour fixe|rollenklärung|reflexion/i.test(`${i.name} ${i.target}`)); const acceptance=Math.round(Math.min(100,20+avg(personas,"trust")*8+avg(personas,"aiLiteracy")*3+avg(personas,"changeEnergy")*4+(hasParticipation?16:0)+res*.15-risky.length*4)); const governance=Math.round(Math.min(100,30+avg(personas,"riskSense")*5+(hasPrivacy?22:0)+res*.18)); const learning=Math.round(Math.min(100,25+avg(personas,"aiLiteracy")*7+avg(personas,"changeEnergy")*5+interventions.length*5)); const risk=Math.round(Math.max(0,100-(acceptance*.35+governance*.4+learning*.15+res*.1))); const bestStrategy=[...strategies].sort((a,b)=>strategyScore(b)-strategyScore(a))[0]; return {acceptance,governance,learning,resources:Math.round(res),risk,risky,deficits:resources.filter(r=>resourceGap(r)>0),bestStrategy}; }
function loadSaved(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY)||"[]")}catch{return[]}} function persistSaved(items){localStorage.setItem(STORAGE_KEY,JSON.stringify(items))}
function reportTitle(key){const m={executiveSummary:"Executive Summary",ausgangslage:"Ausgangslage",simulationsannahmen:"Simulationsannahmen",stakeholderanalyse:"Persona- und Stakeholderanalyse",ressourcenRisikolage:"Ressourcen- und Risikolage",phasenanalyse:"Phasenanalyse",konfliktKoalitionsmuster:"Konflikt- und Koalitionsmuster",kritischeKipppunkte:"Kritische Kipppunkte",interventionsoptionen:"Interventionsoptionen",entscheidungsmatrix:"Entscheidungsmatrix",massnahmenplan:"Maßnahmenplan",offeneFragen:"Offene Fragen",governanceHinweise:"Datenschutz-/Governance-Hinweise",grenzenDerSimulation:"Grenzen der Simulation"};return m[key]||key}

function Card({children,className=""}){return <section className={`rounded-2xl border border-slate-200 bg-white p-5 shadow-sm ${className}`}>{children}</section>}
function Button({children,onClick,dark=false,disabled=false}){return <button disabled={disabled} onClick={onClick} className={`${dark?"bg-slate-900 text-white":"bg-white text-slate-800 border border-slate-200"} rounded-xl px-3 py-2 text-sm font-bold disabled:opacity-50`}>{children}</button>}
function Field({label,value,onChange,area=false}){const c="w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm outline-none focus:ring-4 focus:ring-slate-100";return <label className="block"><span className="mb-1 block text-sm font-semibold text-slate-700">{label}</span>{area?<textarea className={`${c} min-h-24`} value={value||""} onChange={e=>onChange(e.target.value)}/>:<input className={c} value={value||""} onChange={e=>onChange(e.target.value)}/>}</label>}
function SelectField({label,value,onChange,options}){return <label className="block"><span className="mb-1 block text-sm font-semibold text-slate-700">{label}</span><select className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm" value={value||""} onChange={e=>onChange(e.target.value)}>{options.map(o=><option key={o} value={o}>{o}</option>)}</select></label>}
function RangeText({label,value,onValue,text,onText,kind}){return <div className="rounded-xl border bg-white p-3"><label><div className="mb-1 flex justify-between text-sm"><b>{label}</b><span>{value||3}/5</span></div><input type="range" min="1" max="5" value={value||3} onChange={e=>{const v=Number(e.target.value);onValue(v);onText(explain(kind,v))}} className="w-full accent-slate-900"/></label><textarea className="mt-2 min-h-20 w-full rounded-xl border bg-slate-50 p-2 text-xs leading-5" value={text||""} onChange={e=>onText(e.target.value)}/></div>}
function ChoiceText({label,value,onValue,text,onText,kind,options}){return <div><SelectField label={label} value={value} options={options} onChange={v=>{onValue(v);onText(explainChoice(kind,v))}}/><textarea className="mt-2 min-h-16 w-full rounded-xl border bg-slate-50 p-2 text-xs leading-5" value={text||""} onChange={e=>onText(e.target.value)}/></div>}
function Mini({title,text}){return <div className="rounded-xl bg-white p-3"><b>{title}</b><p className="mt-2 whitespace-pre-line text-sm text-slate-600">{text||"—"}</p></div>}

function Templates({setState,setTab}){return <Card><h2 className="text-xl font-bold">Standardszenarien</h2><p className="mt-1 text-sm text-slate-600">Vorlagen zum Starten, Demonstrieren und Weiterarbeiten.</p><div className="mt-4 grid gap-4 lg:grid-cols-3">{scenarios.map(s=><div className="rounded-2xl border bg-slate-50 p-4" key={s.id}><div className="mb-2 inline-flex rounded-full bg-white px-3 py-1 text-xs font-bold">{s.label}</div><h3 className="font-bold">{s.title}</h3><p className="mt-2 text-sm text-slate-600">{s.desc}</p><div className="mt-3"><Button dark onClick={()=>{setState(withIds(s));setTab("Ausgangslage")}}>Vorlage laden</Button></div></div>)}</div></Card>}
function Dashboard({sim}){const rows=[["Akzeptanz",sim.acceptance],["Governance",sim.governance],["Ressourcen",sim.resources],["Lernfähigkeit",sim.learning],["Restrisiko",sim.risk]];return <Card><h2 className="text-xl font-bold">Dashboard</h2><div className="mt-4 grid gap-3 md:grid-cols-5">{rows.map(([k,v])=><div className="rounded-2xl border bg-slate-50 p-4" key={k}><div className="text-sm font-semibold text-slate-500">{k}</div><div className="text-3xl font-bold">{v}</div><div className="mt-2 h-2 rounded bg-slate-200"><div className="h-2 rounded bg-slate-900" style={{width:`${Math.max(0,Math.min(100,v))}%`}}/></div></div>)}</div><p className="mt-4 text-sm text-slate-600">Empfohlene Strategie: <b>{sim.bestStrategy?.name||"keine"}</b></p></Card>}
function Context({state,setState}){const u=(k,v)=>setState(s=>({...s,context:{...s.context,[k]:v}}));return <Card><h2 className="text-xl font-bold">Ausgangslage</h2><div className="mt-4 grid gap-4 md:grid-cols-2"><Field label="Titel" value={state.context.title} onChange={v=>u("title",v)}/><Field label="Domäne" value={state.context.domain} onChange={v=>u("domain",v)}/><div className="md:col-span-2"><Field area label="Entscheidungsfrage" value={state.context.decisionQuestion} onChange={v=>u("decisionQuestion",v)}/></div><Field area label="Ziel" value={state.context.goal} onChange={v=>u("goal",v)}/><Field area label="Grenzen / Nicht-Zwecke" value={state.context.boundaries} onChange={v=>u("boundaries",v)}/></div></Card>}
function Assumptions({items,setItems}){const upd=(id,k,v)=>setItems(items.map(x=>x.id===id?{...x,[k]:v}:x));return <Card><div className="flex justify-between"><h2 className="text-xl font-bold">Annahmen</h2><Button dark onClick={()=>setItems([...items,{id:uid(),text:"Neue Annahme",source:"manuell",evidence:"niedrig",evidenceText:explainChoice("evidence","niedrig"),uncertainty:"mittel",uncertaintyText:explainChoice("uncertainty","mittel"),sensitivity:"intern",sensitivityText:explainChoice("sensitivity","intern"),sourceStatus:"Hypothese",sourceStatusText:explainChoice("sourceStatus","Hypothese")}])}>+ Hinzufügen</Button></div><div className="mt-4 space-y-4">{items.map(a=><div className="rounded-2xl border bg-slate-50 p-4" key={a.id}><div className="grid gap-4 md:grid-cols-2"><Field area label="Annahme" value={a.text} onChange={v=>upd(a.id,"text",v)}/><Field label="Quelle" value={a.source} onChange={v=>upd(a.id,"source",v)}/><ChoiceText label="Evidenz" value={a.evidence} onValue={v=>upd(a.id,"evidence",v)} text={a.evidenceText} onText={v=>upd(a.id,"evidenceText",v)} kind="evidence" options={menu.evidence}/><ChoiceText label="Unsicherheit" value={a.uncertainty} onValue={v=>upd(a.id,"uncertainty",v)} text={a.uncertaintyText} onText={v=>upd(a.id,"uncertaintyText",v)} kind="uncertainty" options={menu.uncertainty}/><ChoiceText label="Sensibilität" value={a.sensitivity} onValue={v=>upd(a.id,"sensitivity",v)} text={a.sensitivityText} onText={v=>upd(a.id,"sensitivityText",v)} kind="sensitivity" options={menu.sensitivity}/><ChoiceText label="Status" value={a.sourceStatus} onValue={v=>upd(a.id,"sourceStatus",v)} text={a.sourceStatusText} onText={v=>upd(a.id,"sourceStatusText",v)} kind="sourceStatus" options={menu.sourceStatus}/></div><button className="mt-3 text-sm font-bold text-rose-700" onClick={()=>setItems(items.filter(x=>x.id!==a.id))}>löschen</button></div>)}</div></Card>}
function Personas({items,setItems}){const upd=(id,k,v)=>setItems(items.map(x=>x.id===id?{...x,[k]:v}:x));const add=()=>setItems([...items,{id:uid(),name:"Neue Rolle",role:"Stakeholder",stance:"unklar",informalRole:"keine besondere informelle Rolle",conflictStyle:"unklar",influence:3,influenceText:explain("influence",3),affectedness:3,affectednessText:explain("affectedness",3),trust:3,trustText:explain("trust",3),aiLiteracy:3,aiLiteracyText:explain("aiLiteracy",3),riskSense:3,riskSenseText:explain("riskSense",3),changeEnergy:3,changeEnergyText:explain("changeEnergy",3),trigger:"",learningNeed:"",communicationNeed:""}]);return <Card><div className="flex justify-between"><h2 className="text-xl font-bold">Personas</h2><Button dark onClick={add}>+ Hinzufügen</Button></div><div className="mt-4 space-y-4">{items.map(p=><div className="rounded-2xl border bg-slate-50 p-4" key={p.id}><div className="grid gap-4 md:grid-cols-2"><Field label="Name" value={p.name} onChange={v=>upd(p.id,"name",v)}/><SelectField label="Rolle" value={p.role} onChange={v=>upd(p.id,"role",v)} options={menu.role}/><SelectField label="Haltung" value={p.stance} onChange={v=>upd(p.id,"stance",v)} options={menu.stance}/><SelectField label="Informelle Rolle" value={p.informalRole} onChange={v=>upd(p.id,"informalRole",v)} options={menu.informalRole}/><SelectField label="Konfliktstil" value={p.conflictStyle} onChange={v=>upd(p.id,"conflictStyle",v)} options={menu.conflictStyle}/><Field label="Trigger" value={p.trigger} onChange={v=>upd(p.id,"trigger",v)}/><RangeText label="Einfluss" value={p.influence} onValue={v=>upd(p.id,"influence",v)} text={p.influenceText} onText={v=>upd(p.id,"influenceText",v)} kind="influence"/><RangeText label="Betroffenheit" value={p.affectedness} onValue={v=>upd(p.id,"affectedness",v)} text={p.affectednessText} onText={v=>upd(p.id,"affectednessText",v)} kind="affectedness"/><RangeText label="Vertrauen" value={p.trust} onValue={v=>upd(p.id,"trust",v)} text={p.trustText} onText={v=>upd(p.id,"trustText",v)} kind="trust"/><RangeText label="KI-Kompetenz" value={p.aiLiteracy} onValue={v=>upd(p.id,"aiLiteracy",v)} text={p.aiLiteracyText} onText={v=>upd(p.id,"aiLiteracyText",v)} kind="aiLiteracy"/><RangeText label="Risikoempfinden" value={p.riskSense} onValue={v=>upd(p.id,"riskSense",v)} text={p.riskSenseText} onText={v=>upd(p.id,"riskSenseText",v)} kind="riskSense"/><RangeText label="Veränderungsenergie" value={p.changeEnergy} onValue={v=>upd(p.id,"changeEnergy",v)} text={p.changeEnergyText} onText={v=>upd(p.id,"changeEnergyText",v)} kind="changeEnergy"/><Field area label="Lernbedarf" value={p.learningNeed} onChange={v=>upd(p.id,"learningNeed",v)}/><Field area label="Kommunikationsbedarf" value={p.communicationNeed} onChange={v=>upd(p.id,"communicationNeed",v)}/></div><button className="mt-3 text-sm font-bold text-rose-700" onClick={()=>setItems(items.filter(x=>x.id!==p.id))}>löschen</button></div>)}</div></Card>}
function Resources({items,setItems}){const upd=(id,k,v)=>setItems(items.map(x=>x.id===id?{...x,[k]:v}:x));const add=()=>setItems([...items,{id:uid(),name:"Neue Ressource",type:"sozial",current:3,currentText:explain("current",3),target:4,targetText:explain("target",4),direction:"high_good",directionText:explainChoice("direction","high_good"),trend:"stabil",trendText:explainChoice("trend","stabil"),bottleneck:"",owner:""}]);return <Card><div className="flex justify-between"><h2 className="text-xl font-bold">Ressourcen</h2><Button dark onClick={add}>+ Hinzufügen</Button></div><div className="mt-4 space-y-4">{items.map(r=><div className="rounded-2xl border bg-slate-50 p-4" key={r.id}><div className="grid gap-4 md:grid-cols-2"><Field label="Ressource" value={r.name} onChange={v=>upd(r.id,"name",v)}/><SelectField label="Typ" value={r.type} onChange={v=>upd(r.id,"type",v)} options={menu.resourceType}/><ChoiceText label="Logik" value={r.direction} onValue={v=>upd(r.id,"direction",v)} text={r.directionText} onText={v=>upd(r.id,"directionText",v)} kind="direction" options={menu.direction}/><ChoiceText label="Trend" value={r.trend} onValue={v=>upd(r.id,"trend",v)} text={r.trendText} onText={v=>upd(r.id,"trendText",v)} kind="trend" options={menu.trend}/><RangeText label="Aktueller Wert" value={r.current} onValue={v=>upd(r.id,"current",v)} text={r.currentText} onText={v=>upd(r.id,"currentText",v)} kind="current"/><RangeText label="Zielwert" value={r.target} onValue={v=>upd(r.id,"target",v)} text={r.targetText} onText={v=>upd(r.id,"targetText",v)} kind="target"/><Field area label="Engpass / Kipprisiko" value={r.bottleneck} onChange={v=>upd(r.id,"bottleneck",v)}/><Field area label="Beobachten / Verantwortlich" value={r.owner} onChange={v=>upd(r.id,"owner",v)}/></div><button className="mt-3 text-sm font-bold text-rose-700" onClick={()=>setItems(items.filter(x=>x.id!==r.id))}>löschen</button></div>)}</div></Card>}
function Interventions({items,setItems}){const upd=(id,k,v)=>setItems(items.map(x=>x.id===id?{...x,[k]:v}:x));const add=()=>setItems([...items,{id:uid(),name:"Neue Intervention",timing:"offen",timingText:"Zeitpunkt fachlich prüfen.",target:"",benefit:"",sideEffect:"",effort:"mittel",effortText:explainChoice("effort","mittel")}]);return <Card><div className="flex justify-between"><h2 className="text-xl font-bold">Interventionen</h2><Button dark onClick={add}>+ Hinzufügen</Button></div><div className="mt-4 space-y-4">{items.map(i=><div className="rounded-2xl border bg-slate-50 p-4" key={i.id}><div className="grid gap-4 md:grid-cols-2"><Field label="Name" value={i.name} onChange={v=>upd(i.id,"name",v)}/><SelectField label="Zeitpunkt" value={i.timing} onChange={v=>{upd(i.id,"timing",v);upd(i.id,"timingText",`Intervention im Abschnitt „${v}“ einplanen und mit Ziel sowie Nebenwirkung prüfen.`)}} options={menu.timing}/><Field area label="Zeitpunkt-Begründung" value={i.timingText} onChange={v=>upd(i.id,"timingText",v)}/><Field label="Ziel" value={i.target} onChange={v=>upd(i.id,"target",v)}/><Field area label="Nutzen" value={i.benefit} onChange={v=>upd(i.id,"benefit",v)}/><Field area label="Nebenwirkung" value={i.sideEffect} onChange={v=>upd(i.id,"sideEffect",v)}/><ChoiceText label="Aufwand" value={i.effort} onValue={v=>upd(i.id,"effort",v)} text={i.effortText} onText={v=>upd(i.id,"effortText",v)} kind="effort" options={menu.effort}/></div><button className="mt-3 text-sm font-bold text-rose-700" onClick={()=>setItems(items.filter(x=>x.id!==i.id))}>löschen</button></div>)}</div></Card>}
function Strategies({items,setItems}){const upd=(id,k,v)=>setItems(items.map(x=>x.id===id?{...x,[k]:v}:x));return <Card><h2 className="text-xl font-bold">Strategien</h2><p className="text-sm text-slate-600">Slider ändern automatisch die Begründungstexte; alle Subtexte bleiben überschreibbar.</p><div className="mt-4 space-y-4">{items.map(st=><div className="rounded-2xl border bg-slate-50 p-4" key={st.id}><Field label="Name" value={st.name} onChange={v=>upd(st.id,"name",v)}/><div className="mt-3"><Field area label="Grundidee" value={st.description} onChange={v=>upd(st.id,"description",v)}/></div><div className="mt-4 grid gap-3 lg:grid-cols-5">{[["speed","Tempo","speedText"],["acceptance","Akzeptanz","acceptanceText"],["control","Kontrolle","controlText"],["innovation","Innovation","innovationText"],["risk","Risiko","riskText"]].map(([k,l,tk])=><RangeText key={k} label={l} value={st[k]} onValue={v=>upd(st.id,k,v)} text={st[tk]} onText={v=>upd(st.id,tk,v)} kind={k}/>)}</div><div className="mt-3 grid gap-3 md:grid-cols-3"><Field area label="Bedingungen" value={st.conditions} onChange={v=>upd(st.id,"conditions",v)}/><Field area label="Scheiternsmodus" value={st.failureMode} onChange={v=>upd(st.id,"failureMode",v)}/><Field area label="Entscheidungssignal" value={st.decisionSignal} onChange={v=>upd(st.id,"decisionSignal",v)}/></div></div>)}</div></Card>}
function ImportPanel({setState,setTab}){const [text,setText]=useState("");const [draft,setDraft]=useState(null);const [documentType,setDocumentType]=useState("Konzept");const [analysisMode,setAnalysisMode]=useState("beratend");const [status,setStatus]=useState("idle");const [err,setErr]=useState("");async function runImport(){setStatus("loading");setErr("");try{const res=await fetch("/api/import-scenario",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({text,documentType,analysisMode})});if(!res.ok)throw new Error(await res.text());setDraft(normalizeDraft(await res.json()));setStatus("done")}catch(e){setErr(String(e.message||e));setStatus("error")}}async function file(e){const f=e.target.files?.[0];if(!f)return;if(f.size>1024*1024){setErr("Datei größer als 1 MB.");return}if(!f.name.toLowerCase().match(/\.(txt|md|json)$/)&&!f.type.startsWith("text/")){setErr("Upload Light unterstützt aktuell TXT, MD, JSON und reine Textdateien.");return}setText(await f.text())}return <Card><h2 className="text-xl font-bold">Import Light</h2><div className="mt-4 grid gap-4 md:grid-cols-3"><SelectField label="Dokumenttyp" value={documentType} onChange={setDocumentType} options={menu.documentType}/><SelectField label="Analysemodus" value={analysisMode} onChange={setAnalysisMode} options={menu.analysisMode}/><label><span className="mb-1 block text-sm font-semibold">Datei hochladen</span><input type="file" accept=".txt,.md,.json,text/*" onChange={file} className="w-full rounded-xl border bg-white p-2 text-sm"/></label></div><textarea className="mt-4 min-h-64 w-full rounded-2xl border p-4 text-sm" value={text} onChange={e=>setText(e.target.value)} placeholder="Konzepttext einfügen oder Textdatei hochladen."/><div className="mt-3 flex gap-2"><Button dark disabled={status==="loading"||text.trim().length<80} onClick={runImport}>{status==="loading"?"Analysiere ...":"Szenarioentwurf erzeugen"}</Button>{draft&&<Button onClick={()=>setDraft(null)}>Entwurf verwerfen</Button>}</div>{err&&<div className="mt-3 rounded-xl bg-rose-50 p-3 text-sm text-rose-800">{err}</div>}{draft&&<div className="mt-5 rounded-2xl border bg-slate-50 p-4"><h3 className="font-bold">Review vor Übernahme</h3><p className="text-sm text-slate-600">Der Entwurf ersetzt erst nach deiner Bestätigung das aktuelle Szenario.</p><div className="mt-3 flex flex-wrap gap-2">{[`Annahmen ${draft.assumptions.length}`,`Personas ${draft.personas.length}`,`Ressourcen ${draft.resources.length}`,`Interventionen ${draft.interventions.length}`,`Strategien ${draft.strategies.length}`].map(x=><span key={x} className="rounded-full bg-white px-3 py-1 text-sm font-semibold">{x}</span>)}</div><div className="mt-4 grid gap-4 md:grid-cols-2"><Mini title="Ausgangslage" text={`${draft.context.title}\n${draft.context.decisionQuestion}`}/><Mini title="Offene Fragen" text={draft.openQuestions.join("\n")}/><Mini title="Warnungen" text={draft.warnings.join("\n")}/><Mini title="Erste Annahmen" text={draft.assumptions.slice(0,5).map(a=>`${a.sourceStatus}: ${a.text}`).join("\n")}/></div><div className="mt-4"><Button dark onClick={()=>{setState(draft);setDraft(null);setTab("Ausgangslage")}}>Entwurf übernehmen</Button></div></div>}</Card>}
function Report({state,sim}){const [status,setStatus]=useState("local"),[gpt,setGpt]=useState(null);async function run(){setStatus("loading");try{const r=await fetch("/api/simulate",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({state})});if(!r.ok)throw new Error(await r.text());setGpt(await r.json());setStatus("done")}catch{setStatus("error")}}const sections=gpt?Object.entries(gpt).map(([k,v])=>[reportTitle(k),v]):[["Executive Summary",`${state.context.title}\nAkzeptanz ${sim.acceptance}, Governance ${sim.governance}, Ressourcen ${sim.resources}, Restrisiko ${sim.risk}.`],["Ressourcenengpässe",sim.deficits.map(r=>`${r.name}: ${r.bottleneck}`).join("\n")||"keine"],["Riskante Annahmen",sim.risky.map(a=>a.text).join("\n")||"keine"],["Strategie",sim.bestStrategy?.name||"keine"]];return <Card><div className="flex justify-between"><h2 className="text-xl font-bold">Report</h2><div className="flex gap-2"><Button onClick={run}>GPT-Report</Button><Button dark onClick={()=>navigator.clipboard?.writeText(sections.map(([a,b])=>`${a}\n${b}`).join("\n\n"))}>Kopieren</Button></div></div><p className="mt-2 text-sm text-slate-500">Status: {status}</p><div className="mt-4 grid gap-3 md:grid-cols-2">{sections.map(([k,v])=><div className="rounded-2xl border bg-slate-50 p-4" key={k}><b>{k}</b><p className="mt-2 whitespace-pre-line text-sm">{String(v)}</p></div>)}</div></Card>}
function Storage({state,setState,saved,setSaved}){const [name,setName]=useState(state.context.title);function save(){const item={id:uid(),name:name||state.context.title,date:new Date().toISOString(),state};const next=[item,...saved];setSaved(next);persistSaved(next)}function load(item){setState(item.state)}function duplicate(item){const next=[{id:uid(),name:item.name+" Kopie",date:new Date().toISOString(),state:item.state},...saved];setSaved(next);persistSaved(next)}function del(id){const next=saved.filter(x=>x.id!==id);setSaved(next);persistSaved(next)}return <Card><h2 className="text-xl font-bold">Speichern und Laden</h2><div className="mt-4 flex gap-2"><input className="flex-1 rounded-xl border p-2" value={name} onChange={e=>setName(e.target.value)}/><Button dark onClick={save}>Aktuelles Szenario speichern</Button></div><div className="mt-4 space-y-3">{saved.map(item=><div className="rounded-2xl border bg-slate-50 p-4" key={item.id}><b>{item.name}</b><div className="text-xs text-slate-500">{new Date(item.date).toLocaleString()}</div><div className="mt-2 flex gap-2"><Button onClick={()=>load(item)}>Laden</Button><Button onClick={()=>duplicate(item)}>Duplizieren</Button><Button onClick={()=>del(item.id)}>Löschen</Button></div></div>)}</div></Card>}
function Compare({saved}){const [a,setA]=useState(""),[b,setB]=useState("");const A=saved.find(x=>x.id===a)?.state,B=saved.find(x=>x.id===b)?.state;const ca=A?compute(A):null,cb=B?compute(B):null;return <Card><h2 className="text-xl font-bold">Vergleich</h2><div className="mt-4 grid gap-3 md:grid-cols-2"><select className="rounded-xl border p-2" value={a} onChange={e=>setA(e.target.value)}><option value="">Simulation A wählen</option>{saved.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select><select className="rounded-xl border p-2" value={b} onChange={e=>setB(e.target.value)}><option value="">Simulation B wählen</option>{saved.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></div>{ca&&cb&&<table className="mt-4 w-full text-sm"><thead><tr><th className="p-2 text-left">Kriterium</th><th>A</th><th>B</th><th>Delta</th></tr></thead><tbody>{[["Akzeptanz","acceptance"],["Governance","governance"],["Ressourcen","resources"],["Lernfähigkeit","learning"],["Restrisiko","risk"]].map(([l,k])=><tr className="border-t" key={k}><td className="p-2 font-semibold">{l}</td><td>{ca[k]}</td><td>{cb[k]}</td><td>{cb[k]-ca[k]}</td></tr>)}</tbody></table>}</Card>}

const tabs=["Dashboard","Vorlagen","Import","Ausgangslage","Annahmen","Personas","Ressourcen","Interventionen","Strategien","Report","Speicher","Vergleich"];
export default function App(){const [state,setState]=useState(initialScenario);const [tab,setTab]=useState("Vorlagen");const [saved,setSaved]=useState([]);useEffect(()=>setSaved(loadSaved()),[]);const sim=useMemo(()=>compute(state),[state]);const set=(key,val)=>setState(s=>({...s,[key]:val}));const views={Dashboard:<Dashboard sim={sim}/>,Vorlagen:<Templates setState={setState} setTab={setTab}/>,Import:<ImportPanel setState={setState} setTab={setTab}/>,Ausgangslage:<Context state={state} setState={setState}/>,Annahmen:<Assumptions items={state.assumptions} setItems={v=>set("assumptions",v)}/>,Personas:<Personas items={state.personas} setItems={v=>set("personas",v)}/>,Ressourcen:<Resources items={state.resources} setItems={v=>set("resources",v)}/>,Interventionen:<Interventions items={state.interventions} setItems={v=>set("interventions",v)}/>,Strategien:<Strategies items={state.strategies} setItems={v=>set("strategies",v)}/>,Report:<Report state={state} sim={sim}/>,Speicher:<Storage state={state} setState={setState} saved={saved} setSaved={setSaved}/>,Vergleich:<Compare saved={saved}/>};return <main className="min-h-screen bg-slate-100 p-4 text-slate-900 md:p-8"><div className="mx-auto max-w-7xl space-y-5"><header className="rounded-3xl bg-slate-950 p-8 text-white"><div className="mb-3 inline-flex rounded-full border border-white/20 px-3 py-1 text-sm">KI-Kernel GPT 0.5</div><h1 className="text-4xl font-bold">Geführte Szenariomodellierung</h1><p className="mt-3 max-w-3xl text-slate-300">Mehr Menüführung, automatische Subtexte und überschreibbare Begründungen für Annahmen, Personas, Ressourcen, Interventionen und Strategien.</p><div className="mt-5 flex gap-3"><Button onClick={()=>{setState(withIds(scenarios[0]));setTab("Ausgangslage")}}>Demo neu laden</Button><a className="rounded-xl border border-white/20 bg-white/10 px-3 py-2 text-sm font-bold" href="/hilfe.html" target="_blank" rel="noreferrer">Hilfe öffnen</a></div></header><nav className="sticky top-2 z-10 overflow-x-auto rounded-2xl border bg-white/90 p-2 shadow-sm backdrop-blur"><div className="flex min-w-max gap-2">{tabs.map(t=><button key={t} onClick={()=>setTab(t)} className={`rounded-xl px-3 py-2 text-sm font-bold ${tab===t?"bg-slate-900 text-white":"text-slate-600 hover:bg-slate-100"}`}>{t}</button>)}<a href="/hilfe.html" target="_blank" rel="noreferrer" className="rounded-xl px-3 py-2 text-sm font-bold text-slate-600 hover:bg-slate-100">Hilfe</a></div></nav>{views[tab]}<footer className="rounded-2xl border bg-white p-4 text-xs text-slate-500">Alle automatisch erzeugten Subtexte sind überschreibbar. Speicherung erfolgt lokal im Browser. Keine echten personenbezogenen Profile verwenden.</footer></div></main>}
